addTopic({id:"mob10",cat:MOB,t:"Push notifications: FCM and APNs",d:"Understand",p:"P1",n:"New",h:1.5,
what:"Push notifications are messages sent from a server to a user's device even when the app isn't open. Apple devices receive them through APNs (Apple Push Notification service); Android devices through Firebase Cloud Messaging (FCM), which can also send to iOS via APNs.",
why:"Notifications drive engagement and important alerts, but overuse makes users turn them off. TPMs coordinate permissions, content, timing and measurement.",
concepts:["Device tokens","FCM and APNs","Notification vs data messages","Permission prompts, especially on iOS and Android 13+","Segmentation, timing and frequency","Delivery and open rate measurement"],
learn:["fcm"],
doIt:"Review the notifications you got this week. Classify each as transactional or marketing and note which you found useful.",
prove:"Write a notification strategy: types, triggers, frequency caps, opt-in prompt timing and success metrics.",
interview:"Our notification opt-in rate is low. What would you do?",
covers:["Push Notifications","FCM, APNs"]},
{sections:[
 {h:"How a push travels",flow:[["Send",[["App server","decides to notify"],["FCM / APNs","platform service"]]],["Receive",[["Device","shows notification"],["App","opens on tap"]]]],flowLabel:"Push notification path",p:["Firebase describes an FCM setup as a trusted environment, such as your app server, that builds and sends messages, plus client apps that receive them through the platform transport: APNs for Apple devices and Android's transport for Android."]},
 {h:"Message types",table:[["Type","Behaviour","Example"],["Notification message","Shown by the system automatically","Your order has shipped"],["Data message","Handled by app code","Silent sync trigger"],["Transactional","Triggered by user's own activity","OTP, delivery update"],["Marketing","Promotions","Sale starts today"]]},
 {h:"Permissions",p:["iOS asks users to allow notifications, and Android 13 and later also require a runtime permission. Ask at a moment when the value is clear, such as after placing an order ('Get delivery updates?'), not at first launch."]},
 {h:"Good practice",bullets:["Cap marketing frequency per user per week.","Respect quiet hours and time zones.","Deep link to the relevant screen.","Measure delivery, open rate and opt-out rate together."]},
 {h:"Key terms",gloss:[["APNs","Apple Push Notification service"],["FCM","Firebase Cloud Messaging"],["Device token","Identifier used to send pushes to one device"],["Opt-in rate","Share of users allowing notifications"],["Data message","A silent message handled by app code"]]}
],
quiz:[["Which service delivers to Apple devices?","APNs."],["When should you ask for notification permission?","When the value is clear, such as after an order."],["What's a data message?","A silent message handled by app code."],["Which metrics should be watched together?","Delivery, open rate and opt-out rate."]],
deeper:["fcm"]},
{prac:["Separate transactional and marketing channels so users can mute promotions without losing order updates.","Review notification opt-outs after each campaign."],
 mis:[["More notifications mean more engagement.","Over-sending drives opt-outs and uninstalls."],["Delivery is guaranteed.","Pushes can be delayed or dropped; critical info needs other channels too."],["Ask for permission on first launch.","Contextual prompts get far higher opt-in."]]});

addTopic({id:"mob11",cat:MOB,t:"Biometrics, permissions and privacy",d:"Understand",p:"P0",n:"New",h:1.5,
what:"Biometric authentication (fingerprint, face) lets users unlock an app or confirm actions using the device's secure hardware; the app never sees the biometric data. Runtime permissions control access to sensitive data and hardware. Store privacy labels and data safety forms disclose what the app collects.",
why:"Privacy and security are review blockers and trust drivers, especially for fintech and health apps. TPMs coordinate permissions, disclosures and security reviews.",
concepts:["Biometric prompt and fallback","Biometrics unlock keys, not passwords","Runtime permissions and rationale","Minimising permissions","App Store privacy labels and Play data safety","OWASP MASVS for mobile security"],
learn:["androidPerms","masvs"],
doIt:"Check the permissions of three apps on your phone. Mark any that seem unnecessary.",
prove:"Write a permissions and privacy plan for a fintech app: each permission, why, when asked, and what's disclosed.",
interview:"How would you add fingerprint login to our banking app safely?",
covers:["Biometric Authentication","Permissions"]},
{sections:[
 {h:"How biometric login works",steps:["User signs in once with password or OTP.","App creates a key in the device's secure hardware, protected by biometrics.","On later launches, the system shows a biometric prompt.","Success unlocks the key, which unlocks the stored session.","Fallback to PIN or password is always available."],p:["The app never receives fingerprints or face data; the OS only reports success or failure."]},
 {h:"Permission best practice",p:["Android's guidance is to ask for a permission in context, when the user starts the feature that needs it, and to explain why if the reason isn't obvious."],bullets:["Request only what's needed.","Handle denial gracefully with an alternative.","Prefer privacy-friendly options: photo picker, approximate location."]},
 {h:"Disclosures",table:[["Store","Disclosure"],["Apple App Store","Privacy nutrition labels and privacy manifests"],["Google Play","Data safety section"]],p:["Third-party SDKs count too; you must disclose what they collect."]},
 {h:"Security baseline",p:["OWASP's MASVS sets baseline security and privacy requirements for mobile apps, covering storage, cryptography, authentication, network, platform interaction, code quality and resilience. Use it as a checklist for security reviews."]},
 {h:"Key terms",gloss:[["Biometric prompt","System dialog for fingerprint or face check"],["Runtime permission","Access the user grants while using the app"],["Permission rationale","Explanation of why a permission is needed"],["Data safety section","Google Play's privacy disclosure"],["MASVS","OWASP's mobile security standard"]]}
],
quiz:[["Does the app receive fingerprint data?","No; the OS only reports success or failure."],["When should permissions be requested?","In context, when the feature is used."],["Do third-party SDKs affect privacy disclosures?","Yes; their data collection must be disclosed."],["What is MASVS?","OWASP's mobile app security verification standard."]],
deeper:["androidPerms","masvs","appReview"]},
{prac:["Keep a permissions register with owner and justification; store reviewers and auditors ask the same questions.","Review SDK data collection before every release that adds or updates one."],
 mis:[["Biometrics replace passwords entirely.","A fallback is always needed."],["Asking for all permissions upfront is efficient.","It lowers grant rates and trust."],["Privacy labels are marketing.","Inaccurate labels can get apps removed."]]});

addTopic({id:"mob12",cat:MOB,t:"Payments, analytics and third-party SDKs",d:"Understand",p:"P0",n:"New",h:2,
what:"Most apps embed third-party SDKs: payment gateways (Razorpay, Stripe, PhonePe, UPI intents), analytics (Mixpanel, Firebase Analytics, Amplitude), crash reporting, maps and chat. Each adds features quickly but also size, risk, privacy duties and upgrade work.",
why:"SDK choices affect revenue, data quality, store compliance and security. TPMs often own vendor evaluation and integration plans.",
concepts:["Payment SDKs and UPI flows","App store rules for digital goods (in-app purchase)","Analytics events and tracking plans","SDK evaluation: size, privacy, support, cost","SDK upgrades and deprecations","Data ownership and consent"],
learn:["appReview","crashlytics"],
doIt:"Write a tracking plan for a checkout flow: 6 to 8 events with names, properties and when they fire.",
prove:"Create an SDK evaluation scorecard and use it to compare two payment or analytics options.",
interview:"How would you choose and integrate an analytics SDK like Mixpanel?",
covers:["Payment Gateway SDK","Analytics SDK","Third-party SDKs","Mixpanel"]},
{sections:[
 {h:"Payments",bullets:["Physical goods and services (food, rides, products) use payment gateways such as Razorpay or Stripe, including UPI.","Digital goods and subscriptions consumed in the app generally must use Apple and Google in-app purchase, subject to each store's current rules and regional exceptions.","Always confirm payment status on the server, not just in the app.","Handle pending and failed states clearly; UPI payments can confirm late."],p:["Apple's App Review Guidelines remind developers that they are responsible for everything in the app complying, including ad networks, analytics services and third-party SDKs."]},
 {h:"Analytics tracking plans",table:[["Event","Properties","Fires when"],["checkout_started","cart_value, item_count","User taps checkout"],["payment_method_selected","method","User picks UPI, card, etc."],["payment_succeeded","order_id, amount, method","Server confirms payment"],["payment_failed","reason, method","Payment fails"]],p:["Agree event names and definitions before build. Inconsistent events are the main reason analytics can't be trusted."]},
 {h:"Evaluating an SDK",table:[["Criterion","Question"],["Fit","Does it meet our needs on both platforms and our framework?"],["Size and performance","How much does it add to app size and start-up?"],["Privacy","What data does it collect; can we control it?"],["Security","Track record, permissions requested"],["Support and roadmap","Active maintenance, SLAs"],["Cost","Pricing at our scale"]]},
 {h:"Key terms",gloss:[["SDK","A third-party library embedded in the app"],["Payment gateway","A service that processes payments"],["In-app purchase","Store-run payments for digital goods"],["Tracking plan","Agreed list of analytics events and properties"],["Event","A recorded user action"]]}
],
quiz:[["Where should payment success be confirmed?","On the server."],["What's a tracking plan?","An agreed list of analytics events, properties and triggers."],["Who is responsible for SDK compliance with store rules?","The app developer."],["Name two SDK evaluation criteria.","Fit, size, privacy, security, support, cost (any two)."]],
deeper:["appReview","crashlytics"]},
{prac:["Make the tracking plan part of the PRD; retrofitting analytics after launch loses the most important data.","Track SDK versions and deprecation dates in a register."],
 mis:[["SDKs are free features.","They add size, risk and maintenance."],["The app can confirm payments.","Client confirmations can be faked; verify server-side."],["Analytics can be added later.","Launch-week data is often the most valuable."]]});

addTopic({id:"mob13",cat:MOB,t:"Builds, signing and provisioning",d:"Understand",p:"P0",n:"New",h:1.5,
what:"Mobile apps are packaged as APK or AAB files (Android) and IPA files (iOS). Every build must be cryptographically signed so devices and stores trust it. Android uses keystores and Play App Signing; iOS uses certificates and provisioning profiles that tie an app to devices and capabilities.",
why:"Lost keys, expired certificates and wrong profiles block releases at the last minute. TPMs should know who owns them and when they expire.",
concepts:["APK vs AAB vs IPA","Signing keys and keystores","Play App Signing and upload keys","Apple certificates and provisioning profiles","Debug vs release builds","Build automation and secret storage"],
learn:["playSigning","testflight"],
doIt:"Find out where your team's signing keys and Apple certificates are stored, who has access and when they expire.",
prove:"Write a release-readiness checklist covering signing, versioning, certificates and build automation.",
interview:"The iOS release is blocked because of a provisioning error. What does that mean?",
covers:["APK, AAB, IPA","App Signing, Keystore","Provisioning Profile"]},
{sections:[
 {h:"Package formats",table:[["Format","Platform","Use"],["APK","Android","Installable package; side-loading and testing"],["AAB","Android","Upload format for Google Play; Play builds optimised APKs per device"],["IPA","iOS","App archive uploaded to App Store Connect"]]},
 {h:"Android signing",p:["Android's docs explain that with Play App Signing, Google manages and protects the app signing key and uses it to sign the APKs it distributes; developers sign uploads with a separate upload key. If the upload key is lost it can be reset, whereas losing a self-managed signing key used to mean you could never update the app."]},
 {h:"iOS signing",bullets:["Certificates identify the developer or team.","App IDs identify the app and its capabilities (push, Apple Pay).","Provisioning profiles bind certificates, app ID and, for development, specific devices.","Certificates and profiles expire and must be renewed."]},
 {h:"Protecting the release process",bullets:["Store keys and certificates in a secure vault or CI secrets, not on one laptop.","Record expiry dates and owners.","Automate builds and signing in CI.","Bump version numbers consistently."]},
 {h:"Key terms",gloss:[["AAB","Android App Bundle, the Play upload format"],["IPA","The iOS app package"],["Keystore","A file holding Android signing keys"],["Provisioning profile","iOS file linking app, certificate and devices"],["Upload key","Key used to sign builds sent to Google Play"]]}
],
quiz:[["Which format do you upload to Google Play?","AAB."],["What does Play App Signing do?","Google stores the app signing key and signs distributed APKs."],["What does a provisioning profile link?","Certificates, app ID, capabilities and (for development) devices."],["Why automate signing in CI?","To avoid reliance on one person's machine and reduce errors."]],
deeper:["playSigning","testflight"]},
{prac:["Add certificate and profile expiry dates to the team calendar with reminders a month ahead.","Ensure at least two people can produce a signed release."],
 mis:[["Signing is a one-time setup.","Certificates expire and keys need protection."],["APK and AAB are the same.","Play requires AAB for new apps and builds APKs from it."],["Anyone can rebuild the app if needed.","Without keys and certificates, releases are blocked."]]});

addTopic({id:"mob14",cat:MOB,t:"Mobile testing and device fragmentation",d:"Understand",p:"P0",n:"New",h:1.5,
what:"Mobile testing combines unit, integration, UI and regression tests with manual testing on emulators (Android), simulators (iOS) and real devices. Device fragmentation means many screen sizes, OS versions, manufacturers and hardware levels must be covered.",
why:"Mobile bugs reach users quickly and fixes take days through store review. A sensible device and test strategy prevents most of the pain.",
concepts:["Unit, integration, UI and regression tests","Emulators, simulators and real devices","Device coverage matrix","Cloud device farms","Pre-launch reports","Network, battery and interruption testing"],
learn:["playTesting","testPyramid"],
doIt:"Build a device matrix for an Indian consumer app: 6 to 8 devices covering low, mid and high-end Android plus two iPhones.",
prove:"Write a mobile test strategy: automated layers, device matrix, manual scenarios, and release regression checklist.",
interview:"How would you decide which devices to test on?",
covers:["Emulator, Simulator","Device Fragmentation","Unit, Integration, UI, Regression Testing"]},
{sections:[
 {h:"Test layers",table:[["Layer","Checks","Runs on"],["Unit","Logic in isolation","CI, fast"],["Integration","Modules together, such as repository and database","CI"],["UI","Screens and flows","Emulators, device farms"],["Regression","Nothing old broke","Before every release"],["Manual exploratory","Real-world feel, edge cases","Real devices"]]},
 {h:"Emulators vs real devices",table:[["Option","Good for","Misses"],["Emulator/simulator","Fast, cheap, automated","Real performance, camera, manufacturer quirks, push"],["Real devices","True behaviour","Cost and scale"],["Cloud device farm","Many real devices on demand","Some cost; less hands-on"]]},
 {h:"Choosing devices",steps:["Use your analytics: top device models, OS versions and screen sizes.","Cover low-end, mid-range and flagship.","Include the oldest supported OS version.","Include major manufacturers whose OS customisations differ.","Revisit quarterly."]},
 {h:"Scenarios often missed",bullets:["Slow and switching networks.","Low battery and power-saving mode.","Interruptions: calls, notifications, app switching.","Large text and dark mode.","Low storage."],p:["Google Play's pre-launch report can also run your app on real devices to flag crashes and issues before release."]},
 {h:"Key terms",gloss:[["Emulator","Software imitating an Android device"],["Simulator","Software imitating an iOS device"],["Fragmentation","Wide variety of devices and OS versions"],["Device farm","A service of real devices for testing"],["Regression testing","Checking existing features still work"]]}
],
quiz:[["What do emulators miss?","Real performance, hardware features and manufacturer quirks."],["How should you pick test devices?","From your own analytics, covering device tiers and oldest OS."],["Name two often-missed scenarios.","Slow networks, low battery, interruptions, large text, low storage (any two)."],["What's a device farm?","A service offering many real devices for testing."]],
deeper:["playTesting","testPyramid"]},
{prac:["Review the device matrix each quarter against analytics; user devices change faster than test labs.","Keep a short manual regression checklist for the top five journeys and run it every release."],
 mis:[["Testing on a flagship phone is enough.","Most users may be on mid or low-end devices."],["Emulators are as good as devices.","They miss real-world behaviour."],["Automation replaces manual testing.","Exploratory testing still finds unique issues."]]});

addTopic({id:"mob15",cat:MOB,t:"Releases: TestFlight, Play Console, store review",d:"Understand",p:"P0",n:"New",h:2,
what:"Mobile releases go through store pipelines. On iOS, builds are uploaded to App Store Connect, tested via TestFlight and submitted for App Review. On Android, builds go to Play Console testing tracks (internal, closed, open) and then production, often as a staged rollout.",
why:"Release timing on mobile depends on review and rollout, not just engineering. TPMs plan buffers, coordinate store listings and manage phased rollouts.",
concepts:["App Store Connect and TestFlight internal/external testers","Play Console testing tracks","App Review and common rejection reasons","Staged and phased rollouts","Release notes and store listings","Halting a bad rollout"],
learn:["testflight","playTesting","appReview"],
doIt:"Map your app's release timeline from code freeze to 100% rollout, including review time buffers on both stores.",
prove:"Write a mobile release runbook: steps, owners, checks, rollout percentages, halt criteria.",
interview:"We need a fix in users' hands by Friday. How do you plan the mobile release?",
covers:["TestFlight, Google Play Console","App Store Review"]},
{sections:[
 {h:"iOS path",steps:["Upload build to App Store Connect.","Internal testers (team members) test via TestFlight immediately.","External testers require a beta app review first.","Submit for App Review with notes and test accounts.","Release manually, automatically or as a phased release over several days."],p:["Apple describes TestFlight as a way to distribute beta builds to testers and collect feedback before releasing to customers."]},
 {h:"Android path",table:[["Track","Who","Notes"],["Internal testing","Up to 100 testers","Available within minutes"],["Closed testing","Chosen groups","Wider feedback; new personal accounts must run one before production"],["Open testing","Anyone who joins","Listed on Google Play"],["Production","All users","Use staged rollout percentages"]],p:["Play Console Help recommends starting with an internal test, then expanding to a small group of closed testers."]},
 {h:"Avoiding rejection",bullets:["Provide demo credentials and clear review notes.","Make sure privacy labels and data safety answers are accurate.","Follow payment rules for digital goods.","Remove placeholder content and broken links.","Request only justified permissions."]},
 {h:"Rollouts",p:["Release to 1% to 10% first, watch crash-free rate and key metrics, then increase. On Play you can halt a staged rollout; on iOS you can pause a phased release. Neither recalls installed versions, so a fix needs a new build."]},
 {h:"Key terms",gloss:[["App Store Connect","Apple's portal for managing apps"],["TestFlight","Apple's beta testing service"],["Testing track","A Play Console release channel for testers"],["Staged rollout","Releasing to a percentage of users"],["App Review","Apple's pre-publication check"]]}
],
quiz:[["Do TestFlight external testers need review?","Yes, a beta app review."],["Name the Play testing tracks.","Internal, closed and open."],["Can a halted rollout remove the app from users who installed it?","No; a new build is needed."],["Give two ways to avoid App Review rejection.","Demo credentials, accurate privacy info, payment rules, no placeholders, justified permissions (any two)."]],
deeper:["testflight","playTesting","appReview"]},
{prac:["Add store review buffers to every mobile plan and say them out loud to stakeholders.","Define rollout halt criteria, such as crash-free users below 99.5%, before releasing."],
 mis:[["Mobile releases are instant like web.","Review and rollout add days."],["Rollout can be undone.","You can stop it, not uninstall it."],["Review rules are predictable.","Have buffers for unexpected questions."]]});

addTopic({id:"mob16",cat:MOB,t:"OTA updates and crash reporting",d:"Understand",p:"P0",n:"New",h:1,
what:"Over-the-air (OTA) updates let cross-platform apps (notably React Native with tools like Expo EAS Update) push JavaScript and asset changes directly to installed apps without a store release, within store rules. Crash reporting tools such as Firebase Crashlytics collect crashes from users' devices so teams can find and fix them.",
why:"OTA updates shorten fix times and crash reporting tells you what's broken. Together they shape mobile incident response.",
concepts:["What OTA can and can't change","Store rules on downloaded code","Channels, rollouts and rollbacks for updates","Crash reports, stack traces and symbol files","Crash-free users and sessions","ANRs and non-fatal errors"],
learn:["easUpdate","crashlytics"],
doIt:"Look at a crash dashboard (or Crashlytics demo screenshots) and identify the top crash, affected users and app versions.",
prove:"Write a mobile incident playbook: crash threshold alerts, triage, OTA fix vs store hotfix, communication.",
interview:"A new release is crashing for 3% of users. Walk me through your response.",
covers:["OTA Updates, Crash Reporting"]},
{sections:[
 {h:"OTA updates",p:["Expo describes EAS Update as a cloud service that serves updates to apps using the expo-updates library, allowing the JavaScript bundle to be updated separately from native code."],table:[["OTA can change","Needs a store release"],["JavaScript logic and UI","Native code and new native libraries"],["Images and text assets","New permissions"],["Bug fixes in JS","Major new functionality that changes the app's purpose"]],bullets:["Use channels and gradual rollouts for updates, and keep rollback ready.","Stay within App Store and Play rules on downloaded code."]},
 {h:"Crash reporting",p:["Firebase Crashlytics groups crashes into issues by impact on real users, with alerts for new, regressed and growing issues. Reports include stack traces, device, OS and app version."],bullets:["Upload symbol files (dSYMs, mapping files) so traces are readable.","Track crash-free users and sessions per release.","On Android, watch ANRs (app not responding) too.","Log non-fatal errors for important failures that don't crash."]},
 {h:"Incident flow",steps:["Alert fires on crash spike for the new version.","Halt or pause the rollout.","Triage the top issue: devices, OS, steps.","Fix via OTA if JS-only, otherwise ship a hotfix build with expedited review if needed.","Communicate to support and stakeholders; monitor recovery."]},
 {h:"Key terms",gloss:[["OTA update","Updating app code without a store release"],["Crash-free users","Share of users with no crashes"],["Symbol file","Maps machine code to readable function names"],["ANR","Android 'App Not Responding' error"],["Non-fatal","A logged error that didn't crash the app"]]}
],
quiz:[["Can OTA updates change native code?","No; native changes need a store release."],["Why upload symbol files?","So crash traces are readable."],["What is an ANR?","Android's 'App Not Responding' error."],["What's the first step when a release crashes widely?","Halt or pause the rollout."]],
deeper:["easUpdate","crashlytics"]},
{prac:["Set a crash-free threshold for each release and alert on it automatically.","Keep OTA updates under the same review and testing discipline as store releases."],
 mis:[["OTA means no testing needed.","Bad OTA updates reach users instantly."],["Crash reports show everything.","Freezes and logic bugs need other signals."],["OTA can fix any bug.","Only JS and asset changes."]]});
